package fraymus.workspace;

import org.json.*;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;

/** Prospective same-world recovery comparison; full costs, failures and original motion retained. */
final class TemporalStudy067 {
    static final String PROTOCOL="temporal-contact-prepush-value-067-v1";
    static final int TOTAL=508;
    private static final class Identity {static final String VALUE=implementation();}
    static String source(){return Identity.VALUE;}
    private static String implementation(){var b=new StringBuilder(PROTOCOL).append(TemporalTrial067.source());try(var in=TemporalStudy067.class.getResourceAsStream("TemporalStudy067.class")){b.append(MapDefinition.sha(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}return MeasurementStore.hash(b.toString());}
    static JSONArray cases(boolean shifted){var random=new Random(shifted?67002:67001);var out=new JSONArray();for(int regime=0;regime<2;regime++)for(int i=0;i<(shifted?6:30);i++){double angle=12+20*random.nextDouble(),ratio=regime==0?.85+.14*random.nextDouble():1.01+.19*random.nextDouble(),center=.02+.34*random.nextDouble();if(shifted)switch(i%3){case 0->angle=10;case 1->angle=34;case 2->ratio=1;}
        out.put(new JSONObject().put("angleDeg",angle).put("frictionRatio",ratio).put("centerM",center).put("halfWidthM",new double[]{.012,.024,.045}[i%3]));}return out;}
    static JSONArray parityCases(){var out=new JSONArray();for(double[] a:new double[][]{{14,.90,.08},{30,.98,.38},{14,1.05,.08},{30,1.18,.38}})out.put(Stopping063.definition(a[0],a[1],a[2]));return out;}
    static JSONObject manifest(){return new JSONObject().put("protocol",PROTOCOL).put("source",source()).put("nativeSource",TemporalTrial067.source()).put("model",Calibration065.info()).put("tasks",cases(false)).put("shifted",cases(true)).put("parityCases",parityCases()).put("methods",new JSONArray(TemporalPolicy067.METHODS)).put("decisionTick",60).put("maximumCorrectionMps",.16).put("maximumTangentMps",.8).put("maximumRotationDeg",10).put("maximumNormalMps",.1).put("maximumAngularRadps",2).put("successReward",1).put("missCost",2).put("refusalCost",.15).put("actionCost",.02).put("observationCost",.03).put("replanCost",.01).put("screenCost",.005).put("contactTicks",new JSONArray(new int[]{52,56,60})).put("geometricGapLimitM",.03).put("valueGain",.05).put("minimumSuccessRate",.4).put("maximumMissRate",.15).put("minimumRecoveryRate",.2).put("total",TOTAL).put("controllerAuthority",false);}
    static JSONObject evaluation(JSONArray rows){var e=TemporalPolicy067.evaluate(rows,true);var groups=new JSONObject();for(String key:List.of("accelerating","slowing","width12mm","width24mm","width45mm")){var subset=new JSONArray();for(Object raw:rows){var task=((JSONObject)raw).getJSONObject("task");boolean match=switch(key){case "accelerating"->task.getDouble("frictionRatio")<1;case "slowing"->task.getDouble("frictionRatio")>1;default->Math.abs(task.getDouble("halfWidthM")-(key.equals("width12mm")?.012:key.equals("width24mm")?.024:.045))<1e-12;};if(match)subset.put(raw);}groups.put(key,TemporalPolicy067.evaluate(subset,false));}return e.put("diagnostics",diagnostics(rows)).put("subgroups",groups).put("qualified",qualifies(e)).put("proposed","value").put("controllerAuthority",false).put("meaning","Empirical native task utility after declared assumed costs; timings are machine-specific diagnostics, not qualification or physical calibration");}
    static JSONObject diagnostics(JSONArray rows){
        int avoided=0,sacrificed=0,accepted=0,disagreements=0,temporalWins=0,temporalLosses=0;double millis=0;
        for(Object raw:rows){var row=(JSONObject)raw;millis+=row.getDouble("screenWallMillis");
            var results=row.getJSONObject("results");var t=results.getJSONObject("temporal").getJSONObject("outcome");var v=results.getJSONObject("value").getJSONObject("outcome");var o=results.getJSONObject("observed").getJSONObject("outcome");
            if(t.getBoolean("executed")&&!v.getBoolean("executed")){if(t.getBoolean("success"))sacrificed++;else avoided++;}
            if(row.getJSONObject("plan").getJSONObject("decisions").getJSONObject("value").has("screen")&&v.getBoolean("executed")){
                accepted++;if(t.getBoolean("success")!=v.getBoolean("success")||Math.abs(t.getDouble("endpointM")-v.getDouble("endpointM"))>1e-6)disagreements++;
            }
            if(t.getBoolean("success")&&!o.getBoolean("success"))temporalWins++;
            if(o.getBoolean("success")&&!t.getBoolean("success"))temporalLosses++;
        }
        return new JSONObject().put("avoidedTemporalMisses",avoided).put("sacrificedTemporalSuccesses",sacrificed)
            .put("acceptedScreenedAttempts",accepted).put("acceptedTemporalDisagreements",disagreements)
            .put("temporalSuccessesObservedMisses",temporalWins).put("observedSuccessesTemporalMisses",temporalLosses)
            .put("screenWallMillis",millis);
    }
    static boolean qualifies(JSONObject e){
        var p=e.getJSONObject("pairedValueMinus");var value=e.getJSONObject("methods").getJSONObject("value");
        for(String key:List.of("fixed","pooled","blind","temporal"))if(p.getJSONObject(key).getDouble("meanDelta")<.05)return false;
        return value.getDouble("allTaskSuccessRate")>=.4&&value.getDouble("allTaskMissRate")<=.15&&value.optDouble("recoveryRate",0)>=.2;
    }
    static JSONObject parityTask(JSONObject c){return new JSONObject().put("angleDeg",c.getDouble("angleDeg")).put("frictionRatio",c.getDouble("frictionRatio")).put("centerM",.1).put("halfWidthM",.045);}
    static JSONObject parityDecision(JSONObject c){return new JSONObject().put("method","simple").put("execute",true).put("recover",false).put("speedMps",c.getDouble("pushMps"));}
    static void run(JSONObject job,Path dir,Runnable cancel,FraynixOutcome061.Progress progress)throws Exception{
        job.put("manifest067",manifest()).put("parity067",new JSONArray()).put("tasks067",new JSONArray()).put("shifted067",new JSONArray()).put("progress",0).put("total",TOTAL).put("nativeExecutions",0);progress.save("Temporal recovery contract retained");
        for(Object raw:parityCases()){cancel.run();var c=(JSONObject)raw;var old=Stopping063.trial(c,"baseline",180,4,dir,cancel);var now=TemporalTrial067.run(parityTask(c),parityDecision(c),dir,cancel,partial->{});double error=TemporalTrial067.parity(old,now);job.getJSONArray("parity067").put(new JSONObject().put("definition",c).put("original",old).put("adapter",now).put("maximumDelta",error));job.put("nativeExecutions",job.getInt("nativeExecutions")+2).put("progress",job.getInt("progress")+1);progress.save("Original runtime parity retained");if(error>1e-6)throw new IllegalStateException("New adapter changed original native motion");}
        for(boolean shifted:new boolean[]{false,true})for(Object raw:cases(shifted)){cancel.run();var task=(JSONObject)raw;double[] screenTiming={0};var initial=TemporalPolicy067.initial(task,screenTiming);double screenMillis=screenTiming[0];var row=new JSONObject().put("task",task).put("plannedAt",Instant.now().toString()).put("plan",initial).put("screenWallMillis",screenMillis).put("results",new JSONObject());job.getJSONArray(shifted?"shifted067":"tasks067").put(row);progress.save("Seven initial plans saved before outcomes");
            for(String method:TemporalPolicy067.METHODS){cancel.run();var decision=row.getJSONObject("plan").getJSONObject("decisions").getJSONObject(method);var result=new JSONObject();row.getJSONObject("results").put(method,result);JSONObject record=null;
                if(decision.getBoolean("execute")){
                    record=TemporalTrial067.run(task,decision,dir,cancel,partial->{result.put("pending",partial);progress.save(method+": tick60 state and correction saved before action");});result.remove("pending");result.put("record",record);job.put("nativeExecutions",job.getInt("nativeExecutions")+1);
                }
                result.put("outcome",TemporalPolicy067.outcome(task,decision,record));job.put("progress",job.getInt("progress")+1);progress.save(method+": actual outcome and cost retained");
            }
        }
        job.put("evaluation067",evaluation(job.getJSONArray("tasks067"))).put("shiftedEvaluation067",TemporalPolicy067.evaluate(job.getJSONArray("shifted067"),true));boolean qualified=job.getJSONObject("evaluation067").getBoolean("qualified");job.put("accepted",qualified).put("reason",qualified?"Value-screened recovery passed declared utility gate; no controller promotion":"Value-screened recovery did not pass declared utility gate; all failures and costs retained");audit(job);progress.save("Temporal recovery comparison verified");
    }
    static void audit(JSONObject job){
        if(!manifest().similar(job.getJSONObject("manifest067")))throw new IllegalStateException("Recovery contract differs");var ids=new HashSet<String>();int count=0;var parity=job.getJSONArray("parity067");if(parity.length()!=4)throw new IllegalStateException("Parity checks incomplete");for(int i=0;i<4;i++){var row=parity.getJSONObject(i);var c=parityCases().getJSONObject(i);var old=row.getJSONObject("original");var now=row.getJSONObject("adapter");double error=TemporalTrial067.parity(old,now);if(!c.similar(row.getJSONObject("definition"))||!c.similar(old.getJSONObject("definition"))||!parityTask(c).similar(now.getJSONObject("task"))||!parityDecision(c).similar(now.getJSONObject("decision"))||error>1e-6||error!=row.getDouble("maximumDelta")||!ids.add(old.getString("id"))||!ids.add(now.getString("id")))throw new IllegalStateException("Parity evidence changed");count+=2;}
        for(boolean shifted:new boolean[]{false,true}){var rows=job.getJSONArray(shifted?"shifted067":"tasks067");var expected=cases(shifted);if(rows.length()!=expected.length())throw new IllegalStateException("Recovery task set incomplete");for(int i=0;i<rows.length();i++){var row=rows.getJSONObject(i);var task=expected.getJSONObject(i);if(!task.similar(row.getJSONObject("task"))||!TemporalPolicy067.initial(task).similar(row.getJSONObject("plan")))throw new IllegalStateException("Initial recovery plan differs");double millis=row.getDouble("screenWallMillis");if(!Double.isFinite(millis)||millis<0||!row.getJSONObject("plan").getJSONObject("decisions").getJSONObject("value").has("screen")&&millis!=0)throw new IllegalStateException("Invalid screen timing");Instant planned=Instant.parse(row.getString("plannedAt"));var results=row.getJSONObject("results");if(!results.keySet().equals(new HashSet<>(TemporalPolicy067.METHODS)))throw new IllegalStateException("Policy result missing or extra");for(String method:TemporalPolicy067.METHODS){var result=results.getJSONObject(method);if(result.has("pending"))throw new IllegalStateException("Recovery still pending");var decision=row.getJSONObject("plan").getJSONObject("decisions").getJSONObject(method);var record=result.optJSONObject("record");if(decision.getBoolean("execute")){if(shifted||record==null)throw new IllegalStateException("Unsupported or missing native execution");TemporalTrial067.verify(record);if(!record.getJSONObject("task").similar(task)||!record.getJSONObject("decision").similar(decision)||!ids.add(record.getString("id"))||Instant.parse(record.getString("startedAt")).isBefore(planned))throw new IllegalStateException("Native identity or prior plan changed");count++;}else if(result.has("record"))throw new IllegalStateException("Refusal fabricates native evidence");if(!TemporalPolicy067.outcome(task,decision,record).similar(result.getJSONObject("outcome")))throw new IllegalStateException("Recovery outcome or cost changed");}}}
        if(job.getInt("progress")!=TOTAL||job.getInt("total")!=TOTAL||job.getInt("nativeExecutions")!=count||!evaluation(job.getJSONArray("tasks067")).similar(job.getJSONObject("evaluation067"))||!TemporalPolicy067.evaluate(job.getJSONArray("shifted067"),true).similar(job.getJSONObject("shiftedEvaluation067"))||job.getBoolean("accepted")!=job.getJSONObject("evaluation067").getBoolean("qualified"))throw new IllegalStateException("Recovery evaluation/counts differ");
    }
    static JSONObject summary(JSONObject j){var out=new JSONObject().put("jobId",j.getString("id")).put("status",j.getString("status")).put("nativeExecutions",j.optInt("nativeExecutions")).put("model",Calibration065.info());if(j.has("evaluation067"))out.put("evaluation",j.getJSONObject("evaluation067")).put("shiftedEvaluation",j.getJSONObject("shiftedEvaluation067"));return out;}
}
